import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ButtonPart = "root" | "loadingIndicator";

export const anatomy: Anatomy<ButtonPart> = createAnatomy("button").parts(
  "root",
  "loadingIndicator",
);

export const parts: Record<ButtonPart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server.
 *
 * The keyboard press *visual* is handled here rather than by the press primitive
 * when the root is a real `<button>`: `data-pressed` has to follow Enter and
 * Space, but the primitive's keyboard mode calls `preventDefault` on Space, which
 * would stop a `type="submit"` button from submitting. Listening without
 * preventing costs six lines and keeps the browser's behaviour intact.
 */

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./button.anatomy";
import { getLoadingIndicatorId, getRootId } from "./button.dom";
import type { ButtonApi, ButtonSchema } from "./button.types";

const ACTIVATION_KEYS: ReadonlySet<string> = new Set(["Enter", " "]);

export function connect<T extends PropTypes>(
  service: Service<ButtonSchema>,
  normalize: NormalizeProps<T>,
): ButtonApi<T> {
  const { context, prop, state, send, scope } = service;

  const disabled = prop("disabled");
  const loading = prop("loading");
  const nativeButton = prop("nativeButton");
  const focusableWhenDisabled = prop("focusableWhenDisabled");
  const pressed = context.get("pressed");
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = state.matches("focused") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  // Two spellings of the same fact. The native attribute takes the control out of
  // the tab order, which is right for a lone button and wrong for a toolbar item
  // that must stay reachable to explain why it cannot be used.
  const nativeDisabled = nativeButton && disabled && !focusableWhenDisabled;
  // Loading is a refusal too: the guard already rejects the activation, and a
  // keyboard user pressing Enter on a busy button otherwise gets silence.
  const ariaDisabled = (disabled && !nativeDisabled) || loading;
  // A substituted element has no native tab order to lose, so it is taken out of
  // it by hand — unless it was asked to stay reachable while disabled.
  const customTabIndex = disabled && !focusableWhenDisabled ? -1 : 0;

  return {
    disabled,
    loading,
    pressed,
    focusSource,
    focusVisible,

    getRootProps: (): T["button"] =>
      normalize.button({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        type: nativeButton ? prop("type") : undefined,
        role: nativeButton ? undefined : "button",
        tabIndex: nativeButton ? undefined : customTabIndex,
        disabled: nativeDisabled,
        "aria-disabled": ariaAttr(ariaDisabled),
        "aria-busy": ariaAttr(loading),
        "data-variant": prop("variant"),
        "data-size": prop("size"),
        "data-disabled": dataAttr(disabled),
        "data-loading": dataAttr(loading),
        "data-pressed": dataAttr(pressed),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.CLICK", originalEvent: event });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || !nativeButton || event.repeat) return;
          if (ACTIVATION_KEYS.has(event.key)) send({ type: "ROOT.PRESS_START" });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || !nativeButton) return;
          if (ACTIVATION_KEYS.has(event.key)) send({ type: "ROOT.PRESS_END" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.BLUR" });
        },
      }),

    getLoadingIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.loadingIndicator.attrs,
        id: getLoadingIndicatorId(scope),
        // `aria-busy` on the root already carries the state; the spinner itself is
        // decoration, and announcing it twice is worse than not at all.
        "aria-hidden": ariaAttr(true),
        "data-loading": dataAttr(loading),
        hidden: !loading,
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "button";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLoadingIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "loadingIndicator");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * A button looks like it needs no machine, and then you write down what it owes:
 * a press state that survives the finger sliding off and back, a loading state
 * that refuses activation without lying to the accessibility tree, a disabled
 * state with two different spellings, and the same behaviour when the root is not
 * a `<button>` at all.
 *
 * Who activates the control depends on that last point, and the split is the one
 * design decision here. On a real `<button>` the browser is already correct:
 * Enter and Space produce a click, forms submit, and the press primitive is used
 * for the pointer *visual* only, with its keyboard handling off — turning it on
 * would `preventDefault` Space and quietly stop `type="submit"` from submitting.
 * On a substituted element there is no native click to wait for, so the press
 * primitive synthesises the APG keyboard behaviour and activation comes from it.
 * Exactly one of the two paths is live at a time, which is what keeps a touch
 * from firing the machine twice through the compatibility click.
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { trackPress } from "../../interaction/press";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getRootEl } from "./button.dom";
import type { ButtonSchema } from "./button.types";

export const machine: Machine<ButtonSchema> = createMachine<ButtonSchema>({
  props({ props }) {
    return {
      type: "button",
      variant: "filled",
      size: "md",
      disabled: false,
      loading: false,
      focusableWhenDisabled: false,
      nativeButton: true,
      ...props,
    };
  },

  context({ bindable }) {
    return {
      pressed: bindable<boolean>(() => ({ defaultValue: false })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackPointerPress"],

  watch({ prop, track, action }) {
    track(
      () => [prop("loading")],
      () => action(["announceLoading", "clearPressed"]),
    );
  },

  on: {
    "ROOT.CLICK": { guard: "isInteractive", actions: ["invokeOnPress"] },
    "ROOT.PRESS": { guard: "isInteractive", actions: ["invokeOnPress"] },
    "ROOT.PRESS_START": { guard: "isInteractive", actions: ["setPressed"] },
    "ROOT.PRESS_END": { actions: ["clearPressed"] },
    "ROOT.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource", "clearPressed"],
      on: { "ROOT.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("loading"),
    },

    actions: {
      invokeOnPress({ prop, event }) {
        // A real button is activated by its own click, a substituted element by the
        // press primitive. Accepting both would double-fire on touch, where the
        // compatibility click follows the pointer sequence.
        const expected = prop("nativeButton") ? "ROOT.CLICK" : "ROOT.PRESS";
        if (event.type !== expected) return;
        prop("onPress")?.({ originalEvent: event.originalEvent });
      },
      setPressed({ context }) {
        context.set("pressed", true);
      },
      clearPressed({ context }) {
        context.set("pressed", false);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
      announceLoading({ prop, scope }) {
        const text = prop("loadingText");
        if (!prop("loading") || text === undefined) return;
        getLiveAnnouncer(scope.getDoc()).announce(text, "polite");
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackPointerPress({ scope, prop, send }) {
        return trackPress(getRootEl(scope), {
          isDisabled: () => prop("disabled") || prop("loading"),
          // Off for a real button: see the note at the top of the file.
          keyboard: !prop("nativeButton"),
          onPressStart: () => send({ type: "ROOT.PRESS_START" }),
          onPressEnd: () => send({ type: "ROOT.PRESS_END" }),
          onPressCancel: () => send({ type: "ROOT.PRESS_END" }),
          onPress: (event) => send({ type: "ROOT.PRESS", originalEvent: event.originalEvent }),
        });
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

/** Button styles (CDC §4.5, research/components.md T1). */
export type ButtonVariant = "filled" | "tinted" | "gray" | "plain" | "glass";

export type ButtonSize = "xs" | "sm" | "md" | "lg" | "xl";

export interface ButtonPressDetails {
  readonly originalEvent: Event;
}

export interface ButtonMachineProps {
  readonly dir?: Direction | undefined;
  readonly type?: "button" | "submit" | "reset" | undefined;
  readonly variant?: ButtonVariant | undefined;
  readonly size?: ButtonSize | undefined;
  readonly disabled?: boolean | undefined;
  /**
   * Busy: activation is refused, the label keeps its width and `aria-busy` says so.
   */
  readonly loading?: boolean | undefined;
  /**
   * Announced politely when `loading` turns on. Without it nothing is announced —
   * a spinner appearing is not news a screen reader has to interrupt for.
   */
  readonly loadingText?: string | undefined;
  /**
   * Keeps the control focusable while disabled: `aria-disabled` instead of the
   * native attribute. Off by default — a disabled button has no reason to stay in
   * the tab order unless it is a toolbar item (APG).
   */
  readonly focusableWhenDisabled?: boolean | undefined;
  /**
   * False when the root is not a real `<button>` (a substituted `<div>`, a card).
   * The adapter sets it from what it renders; it decides who activates the
   * control — the browser's click, or the press primitive's synthesised keyboard.
   */
  readonly nativeButton?: boolean | undefined;
  readonly onPress?: ((details: ButtonPressDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedButtonMachineProps extends ButtonMachineProps {
  readonly type: "button" | "submit" | "reset";
  readonly variant: ButtonVariant;
  readonly size: ButtonSize;
  readonly disabled: boolean;
  readonly loading: boolean;
  readonly focusableWhenDisabled: boolean;
  readonly nativeButton: boolean;
}

export interface ButtonSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedButtonMachineProps;
  context: { pressed: boolean; focusSource: InputModality | null };
  event:
    | { type: "ROOT.CLICK"; originalEvent: Event }
    | { type: "ROOT.PRESS"; originalEvent: Event }
    | { type: "ROOT.PRESS_START" }
    | { type: "ROOT.PRESS_END" }
    | { type: "ROOT.FOCUS" }
    | { type: "ROOT.BLUR" };
  action:
    | "invokeOnPress"
    | "setPressed"
    | "clearPressed"
    | "captureFocusSource"
    | "clearFocusSource"
    | "announceLoading";
  guard: "isInteractive";
  effect: "trackModality" | "trackPointerPress";
}

export interface ButtonApi<T extends PropTypes = PropTypes> {
  readonly disabled: boolean;
  readonly loading: boolean;
  /** True between press-start and press-end — what drives the press motion. */
  readonly pressed: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  getRootProps(): T["button"];
  getLoadingIndicatorProps(): T["element"];
}

export { anatomy, type ButtonPart, parts } from "./button.anatomy";
export { connect } from "./button.connect";
export { getLoadingIndicatorId, getRootEl, getRootId } from "./button.dom";
export { machine } from "./button.machine";
export type {
  ButtonApi,
  ButtonMachineProps,
  ButtonPressDetails,
  ButtonSchema,
  ButtonSize,
  ButtonVariant,
  ResolvedButtonMachineProps,
} from "./button.types";

/**
 * The pattern every T1a component follows: a root that owns the machine and
 * publishes its api, parts that read it, and a `use*` hook underneath for anyone
 * who would rather place the props themselves.
 *
 * `nativeButton` is inferred from what is actually rendered. A substituted `<a>`
 * or `<div>` needs `role="button"`, a tab index and synthesised Enter/Space; a
 * real `<button>` needs none of it and must keep its native click, or a submit
 * button stops submitting. The adapter is the only layer that knows which one it
 * is about to render, so it is the layer that says so.
 */

import * as button from "@standarui/core/button";
import { isValidElement, type ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { type RenderProp, useRender } from "../../use-render";

export type ButtonApi = button.ButtonApi<ReactPropTypes>;

const ButtonContext = createPartContext<ButtonApi>("Button");

export interface UseButtonProps extends button.ButtonMachineProps, MachineRuntimeProps {}

/** The api behind the components — prop getters, state, nothing rendered. */
export function useButton(props: UseButtonProps): ButtonApi {
  return button.connect(useMachine(button.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "type",
  "variant",
  "size",
  "disabled",
  "loading",
  "loadingText",
  "focusableWhenDisabled",
  "nativeButton",
  "onPress",
] as const;

export interface ButtonRootProps extends UseButtonProps, PartProps<"button", UseButtonProps> {}

/** `false` when the element being rendered is not a real `<button>`. */
function isNativeButton(render: RenderProp | undefined, asChild: boolean | undefined): boolean {
  if (asChild === true) return false;
  if (render === undefined) return true;
  // A render function can produce anything; assuming a button would hand it the
  // one behaviour it cannot opt out of.
  if (!isValidElement(render)) return false;
  return render.type === "button";
}

export function ButtonRoot(props: ButtonRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;

  const api = useButton({
    nativeButton: isNativeButton(render, asChild),
    ...machineProps,
  });

  return (
    <ButtonContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "button",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ButtonContext.Provider>
  );
}

export type ButtonLoadingIndicatorProps = PartProps<"span">;

export function ButtonLoadingIndicator(props: ButtonLoadingIndicatorProps): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = ButtonContext.usePart("ButtonLoadingIndicator");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getLoadingIndicatorProps(),
    elementProps,
    children,
  });
}

/**
 * `<Button>` — the bare name beside the parts, and the smallest composed layer
 * there is: one root, three slots, no collection.
 *
 * The gain is not the icon slot. It is `loading`: `ButtonRoot` alone already says
 * `aria-busy` and carries `data-loading`, and then draws nothing, because the
 * spinner is a part — so a consumer who set `loading` and forgot
 * `ButtonLoadingIndicator` got a busy button with no sign of it. Here the part
 * comes with the flag, empty, and `_button.scss` draws the ring under `::after`.
 *
 * `render` and `asChild` travel in `rest` untouched, and that is behaviour rather
 * than passthrough sugar: `ButtonRoot` infers `nativeButton` from the element it
 * is about to render, which is what earns a substituted `<a>` its `role="button"`
 * and its synthesised Enter/Space.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { ButtonLoadingIndicator, ButtonRoot, type UseButtonProps } from "./button";

export interface ButtonComposedProps
  extends UseButtonProps,
    Omit<PartProps<"button", UseButtonProps>, "children"> {
  /** The label. Text, and text is the only thing that names a button. */
  readonly children?: ReactNode;
  /** The leading glyph — an inline SVG, never a text character. */
  readonly icon?: ReactNode;
  /** The trailing one: a chevron, a shortcut, a count. */
  readonly accessory?: ReactNode;
}

export function Button(props: ButtonComposedProps): ReactNode {
  const { children, icon, accessory, ...rest } = props;

  return (
    <ButtonRoot {...rest}>
      {icon}
      {children}
      {accessory}
      {/* Last, and the order is not layout: the indicator is `position: absolute;
          inset: 0` over the whole root, so where it sits among the children moves
          nothing on screen. Last is where the `States` story puts it, and it keeps
          the label first in the DOM for anything reading the source order. */}
      {rest.loading === true ? <ButtonLoadingIndicator /> : null}
    </ButtonRoot>
  );
}

export type {
  ButtonMachineProps,
  ButtonPressDetails,
  ButtonSize,
  ButtonVariant,
} from "@standarui/core/button";
export {
  type ButtonApi,
  ButtonLoadingIndicator,
  type ButtonLoadingIndicatorProps,
  ButtonRoot,
  type ButtonRootProps,
  type UseButtonProps,
  useButton,
} from "./button";
export { Button, type ButtonComposedProps } from "./composed";
